double mean(List<double[]> a,int lo,int hi,int j){double v=0;for(int k=lo;k<hi;k++)v+=a.get(k)[j];return v/(hi-lo);}
double spread(List<double[]> a,int lo,int hi,int j){double low=Double.POSITIVE_INFINITY,high=Double.NEGATIVE_INFINITY;for(int k=lo;k<hi;k++){low=Math.min(low,a.get(k)[j]);high=Math.max(high,a.get(k)[j]);}return high-low;}
